-- IA-07 fixture: exact group C configuration subset, copied from the IA-06
-- base fixture (catalog_configuration_operations/receipts/sources only).
-- Proposed fixture only, no canonical/embed/Capture claim; group C is not embedded.
-- The 105 reclaim indexes remain outside IA-07 (reserved for IA-10).
CREATE TABLE catalog_configuration_operations(
 original_operation_id BLOB PRIMARY KEY CHECK(length(original_operation_id)=16),
 original_request_digest BLOB NOT NULL CHECK(length(original_request_digest)=32),
 command_incarnation BLOB NOT NULL CHECK(length(command_incarnation)=16),
 command_kind TEXT NOT NULL CHECK(command_kind IN('configure_library','configure_source')),
 original_library_id INTEGER NOT NULL REFERENCES catalog_libraries(id) ON DELETE NO ACTION ON UPDATE NO ACTION,
 original_library_key TEXT NOT NULL CHECK(length(original_library_key)>0 AND instr(original_library_key,char(0))=0),
 original_source_id TEXT,
 last_command_sequence INTEGER NOT NULL DEFAULT 0 CHECK(last_command_sequence>=0),
 acknowledged_command_sequence INTEGER NOT NULL DEFAULT 0 CHECK(acknowledged_command_sequence>=0),
 receipt_reclaim_sequence INTEGER NOT NULL DEFAULT 0 CHECK(receipt_reclaim_sequence IN(0,1)),
 receipt_retained_count INTEGER NOT NULL DEFAULT 0 CHECK(receipt_retained_count>=0),
 receipt_retained_bytes INTEGER NOT NULL DEFAULT 0 CHECK(receipt_retained_bytes>=0),
 receipt_reclaim_due_ms INTEGER CHECK(receipt_reclaim_due_ms IS NULL OR receipt_reclaim_due_ms>=0),
 receipt_reclaim_ordinal INTEGER NOT NULL DEFAULT -1 CHECK(receipt_reclaim_ordinal>=-1),
 reclaim_command_sequence INTEGER,
 reclaim_operation_id BLOB,
 reclaim_request_digest BLOB,
 reclaim_command_kind TEXT,
 reclaim_result_version INTEGER,
 reclaim_captured_acknowledged_sequence INTEGER,
 reclaim_old_sequence INTEGER,
 reclaim_removed_sequence INTEGER,
 reclaim_removed_kind TEXT,
 reclaim_removed_count INTEGER,
 reclaim_removed_bytes INTEGER,
 reclaim_result_sequence INTEGER,
 reclaim_result_no_next INTEGER,
 reclaim_result_rows INTEGER,
 reclaim_result_bytes INTEGER,
 reclaim_applied_ms INTEGER,
 reclaim_result_count INTEGER,
 reclaim_result_digest BLOB,
 reclaim_old_ordinal INTEGER,
 reclaim_removed_ordinal INTEGER,
 reclaim_result_ordinal INTEGER,
 reclaim_slot_bytes INTEGER GENERATED ALWAYS AS (CASE WHEN reclaim_operation_id IS NULL THEN 0 ELSE 192+length(CAST(reclaim_command_kind AS BLOB))+length(CAST(reclaim_removed_kind AS BLOB))+CASE WHEN reclaim_removed_sequence IS NULL THEN 0 ELSE 8 END+CASE WHEN reclaim_removed_ordinal IS NULL THEN 0 ELSE 8 END END) VIRTUAL,
 CHECK((reclaim_operation_id IS NULL)=(reclaim_command_sequence IS NULL)),
 CHECK(typeof(reclaim_command_sequence) IN('null','integer')),
 CHECK((reclaim_operation_id IS NULL)=(reclaim_operation_id IS NULL)),
 CHECK(typeof(reclaim_operation_id) IN('null','blob')),
 CHECK((reclaim_operation_id IS NULL)=(reclaim_request_digest IS NULL)),
 CHECK(typeof(reclaim_request_digest) IN('null','blob')),
 CHECK((reclaim_operation_id IS NULL)=(reclaim_command_kind IS NULL)),
 CHECK(typeof(reclaim_command_kind) IN('null','text')),
 CHECK((reclaim_operation_id IS NULL)=(reclaim_result_version IS NULL)),
 CHECK(typeof(reclaim_result_version) IN('null','integer')),
 CHECK((reclaim_operation_id IS NULL)=(reclaim_captured_acknowledged_sequence IS NULL)),
 CHECK(typeof(reclaim_captured_acknowledged_sequence) IN('null','integer')),
 CHECK((reclaim_operation_id IS NULL)=(reclaim_old_sequence IS NULL)),
 CHECK(typeof(reclaim_old_sequence) IN('null','integer')),
 CHECK(typeof(reclaim_removed_sequence) IN('null','integer')),
 CHECK((reclaim_operation_id IS NULL)=(reclaim_removed_kind IS NULL)),
 CHECK(typeof(reclaim_removed_kind) IN('null','text')),
 CHECK((reclaim_operation_id IS NULL)=(reclaim_removed_count IS NULL)),
 CHECK(typeof(reclaim_removed_count) IN('null','integer')),
 CHECK((reclaim_operation_id IS NULL)=(reclaim_removed_bytes IS NULL)),
 CHECK(typeof(reclaim_removed_bytes) IN('null','integer')),
 CHECK((reclaim_operation_id IS NULL)=(reclaim_result_sequence IS NULL)),
 CHECK(typeof(reclaim_result_sequence) IN('null','integer')),
 CHECK((reclaim_operation_id IS NULL)=(reclaim_result_no_next IS NULL)),
 CHECK(typeof(reclaim_result_no_next) IN('null','integer')),
 CHECK((reclaim_operation_id IS NULL)=(reclaim_result_rows IS NULL)),
 CHECK(typeof(reclaim_result_rows) IN('null','integer')),
 CHECK((reclaim_operation_id IS NULL)=(reclaim_result_bytes IS NULL)),
 CHECK(typeof(reclaim_result_bytes) IN('null','integer')),
 CHECK((reclaim_operation_id IS NULL)=(reclaim_applied_ms IS NULL)),
 CHECK(typeof(reclaim_applied_ms) IN('null','integer')),
 CHECK((reclaim_operation_id IS NULL)=(reclaim_result_count IS NULL)),
 CHECK(typeof(reclaim_result_count) IN('null','integer')),
 CHECK((reclaim_operation_id IS NULL)=(reclaim_result_digest IS NULL)),
 CHECK(typeof(reclaim_result_digest) IN('null','blob')),
 CHECK((reclaim_operation_id IS NULL)=(reclaim_old_ordinal IS NULL)),
 CHECK(typeof(reclaim_old_ordinal) IN('null','integer')),
 CHECK(typeof(reclaim_removed_ordinal) IN('null','integer')),
 CHECK((reclaim_operation_id IS NULL)=(reclaim_result_ordinal IS NULL)),
 CHECK(typeof(reclaim_result_ordinal) IN('null','integer')),
 CHECK(last_command_sequence-acknowledged_command_sequence<=1),
 CHECK(reclaim_operation_id IS NULL OR (length(reclaim_operation_id)=16 AND length(reclaim_request_digest)=32 AND length(reclaim_result_digest)=32)),
 CHECK(reclaim_operation_id IS NULL OR (reclaim_command_kind='configuration_receipt_reclaim' AND reclaim_result_version=1 AND reclaim_result_count=1 AND reclaim_applied_ms>=0)),
 CONSTRAINT ia_configuration_gc_sequence CHECK(reclaim_operation_id IS NULL OR (reclaim_command_sequence>1 AND reclaim_command_sequence<=last_command_sequence AND reclaim_captured_acknowledged_sequence>=1 AND reclaim_captured_acknowledged_sequence<=acknowledged_command_sequence AND reclaim_command_sequence-reclaim_captured_acknowledged_sequence=1)),
 CHECK(reclaim_operation_id IS NULL OR (reclaim_old_sequence>=0 AND reclaim_old_sequence<=reclaim_captured_acknowledged_sequence AND reclaim_result_sequence>=reclaim_old_sequence AND reclaim_result_sequence<=reclaim_captured_acknowledged_sequence AND reclaim_removed_count IN(0,1) AND reclaim_removed_bytes>=0 AND reclaim_result_no_next IN(0,1) AND reclaim_result_rows>=0 AND reclaim_result_bytes>=0)),
 CHECK(reclaim_operation_id IS NOT NULL OR reclaim_removed_sequence IS NULL),
 CHECK(reclaim_operation_id IS NULL OR ((reclaim_removed_count=0)=(reclaim_removed_sequence IS NULL))),
 CHECK(reclaim_operation_id IS NULL OR ((reclaim_result_rows=0)=(reclaim_result_bytes=0))),
 CHECK(reclaim_operation_id IS NULL OR ((reclaim_result_rows=0)=(reclaim_result_no_next=1))),
 CHECK(reclaim_operation_id IS NULL OR reclaim_result_sequence=receipt_reclaim_sequence),
 CHECK(reclaim_operation_id IS NULL OR reclaim_command_sequence<>last_command_sequence OR ((reclaim_result_no_next=1)=(receipt_reclaim_due_ms IS NULL))),
 CONSTRAINT ia_configuration_gc_debt CHECK(reclaim_operation_id IS NULL OR reclaim_command_sequence<>last_command_sequence OR (reclaim_result_rows=receipt_retained_count AND reclaim_result_bytes=receipt_retained_bytes)),
 CHECK(reclaim_operation_id IS NULL OR reclaim_removed_count<>0 OR (reclaim_removed_kind='none' AND reclaim_removed_bytes=0 AND reclaim_result_sequence=reclaim_old_sequence AND reclaim_result_no_next=1)),
 CHECK(reclaim_operation_id IS NULL OR reclaim_removed_count<>1 OR (reclaim_removed_sequence>reclaim_old_sequence AND reclaim_removed_sequence<=reclaim_captured_acknowledged_sequence AND reclaim_removed_bytes>0)),
 CHECK(receipt_reclaim_sequence=0 OR receipt_reclaim_ordinal=-1),
 CONSTRAINT ia_configuration_gc_cursor CHECK(reclaim_operation_id IS NOT NULL OR (receipt_reclaim_sequence=0 AND receipt_reclaim_ordinal=-1)),
 CHECK(reclaim_operation_id IS NOT NULL OR reclaim_removed_ordinal IS NULL),
 CHECK(reclaim_operation_id IS NULL OR (reclaim_old_sequence IN(0,1) AND reclaim_result_sequence IN(0,1) AND reclaim_old_ordinal>=-1 AND reclaim_result_ordinal>=-1 AND reclaim_result_ordinal=receipt_reclaim_ordinal AND reclaim_removed_kind IN('none','source','header'))),
 CHECK(reclaim_operation_id IS NULL OR reclaim_removed_kind<>'source' OR (reclaim_removed_count=1 AND reclaim_removed_sequence=1 AND reclaim_old_sequence=0 AND reclaim_result_sequence=0 AND reclaim_removed_ordinal IS NOT NULL AND reclaim_removed_ordinal>=0 AND reclaim_removed_ordinal-reclaim_old_ordinal=1 AND reclaim_result_ordinal=reclaim_removed_ordinal AND reclaim_result_no_next=0)),
 CHECK(reclaim_operation_id IS NULL OR reclaim_removed_kind='source' OR reclaim_removed_ordinal IS NULL),
 CHECK(reclaim_operation_id IS NULL OR reclaim_removed_kind<>'header' OR (reclaim_removed_count=1 AND reclaim_removed_sequence=1 AND reclaim_old_sequence=0 AND reclaim_result_sequence=1 AND reclaim_result_ordinal=-1 AND reclaim_result_no_next=1)),
 CHECK(reclaim_operation_id IS NULL OR reclaim_removed_count<>0 OR reclaim_result_ordinal=reclaim_old_ordinal),
 CHECK((command_kind='configure_source')=(original_source_id IS NOT NULL)),
 CHECK(original_source_id IS NULL OR (length(original_source_id)>0 AND instr(original_source_id,char(0))=0)),
 CHECK(receipt_reclaim_sequence<=acknowledged_command_sequence AND acknowledged_command_sequence<=last_command_sequence),
 CHECK((receipt_retained_count=0)=(receipt_retained_bytes=0)),
 CHECK(typeof(original_operation_id)='blob'),
 CHECK(typeof(original_request_digest)='blob'),
 CHECK(typeof(command_incarnation)='blob'),
 CHECK(typeof(command_kind)='text'),
 CHECK(typeof(original_library_id)='integer' AND original_library_id>0),
 CHECK(typeof(original_library_key)='text'),
 CHECK(typeof(original_source_id) IN('null','text')),
 CHECK(typeof(last_command_sequence)='integer'),
 CHECK(typeof(acknowledged_command_sequence)='integer'),
 CHECK(typeof(receipt_reclaim_sequence)='integer'),
 CHECK(typeof(receipt_retained_count)='integer'),
 CHECK(typeof(receipt_retained_bytes)='integer')
) WITHOUT ROWID, STRICT;
CREATE UNIQUE INDEX catalog_configuration_operation_kind ON catalog_configuration_operations(original_operation_id,command_incarnation,command_kind);
CREATE INDEX catalog_configuration_original_library ON catalog_configuration_operations(original_library_id);
CREATE TABLE catalog_configuration_receipts(
 original_operation_id BLOB NOT NULL CHECK(length(original_operation_id)=16),
 command_incarnation BLOB NOT NULL CHECK(length(command_incarnation)=16),
 command_sequence INTEGER NOT NULL CHECK(command_sequence=1),
 operation_id BLOB NOT NULL UNIQUE CHECK(length(operation_id)=16 AND operation_id=original_operation_id),
 request_digest BLOB NOT NULL CHECK(length(request_digest)=32),
 command_kind TEXT NOT NULL CHECK(command_kind IN('configure_library','configure_source')),
 result_version INTEGER NOT NULL CHECK(result_version=1),
 accepted_revision INTEGER NOT NULL CHECK(accepted_revision>0),
 applied_ms INTEGER NOT NULL CHECK(applied_ms>=0),
 result_library_name TEXT,
 result_library_kind TEXT,
 result_count INTEGER NOT NULL CHECK(result_count>0),
 result_digest BLOB NOT NULL CHECK(length(result_digest)=32),
 retained_bytes INTEGER NOT NULL CHECK(retained_bytes=160+length(CAST(command_kind AS BLOB))+coalesce(length(CAST(result_library_name AS BLOB)),0)+coalesce(length(CAST(result_library_kind AS BLOB)),0)),
 CHECK((command_kind='configure_library')=(result_library_name IS NOT NULL)),
 CHECK((command_kind='configure_library')=(result_library_kind IS NOT NULL)),
 CHECK(result_library_name IS NULL OR length(result_library_name)>0),
 CHECK(result_library_kind IS NULL OR length(result_library_kind)>0),
 CHECK(command_kind<>'configure_source' OR result_count=1),
 PRIMARY KEY(original_operation_id,command_incarnation,command_sequence,command_kind),
 FOREIGN KEY(original_operation_id,command_incarnation,command_kind)
 REFERENCES catalog_configuration_operations(original_operation_id,command_incarnation,command_kind)
 ON DELETE NO ACTION ON UPDATE NO ACTION
) WITHOUT ROWID, STRICT;
CREATE TABLE catalog_configuration_sources(
 original_operation_id BLOB NOT NULL CHECK(length(original_operation_id)=16),
 command_incarnation BLOB NOT NULL CHECK(length(command_incarnation)=16),
 command_sequence INTEGER NOT NULL CHECK(command_sequence=1),
 command_kind TEXT NOT NULL CHECK(command_kind IN('configure_library','configure_source')),
 ordinal INTEGER NOT NULL CHECK(ordinal>=0),
 source_id TEXT NOT NULL CHECK(length(source_id)>0 AND instr(source_id,char(0))=0),
 source_name TEXT NOT NULL,
 source_incarnation TEXT NOT NULL CHECK(length(source_incarnation)>0),
 source_generation INTEGER NOT NULL CHECK(source_generation>0),
 configured_root TEXT NOT NULL CHECK(length(configured_root)>0 AND instr(configured_root,char(0))=0),
 resolved_root TEXT NOT NULL CHECK(length(resolved_root)>0 AND instr(resolved_root,char(0))=0),
 root_identity TEXT NOT NULL CHECK(length(root_identity)>0),
 source_kind TEXT NOT NULL CHECK(source_kind IN('local','remote')),
 classification TEXT NOT NULL CHECK(classification IN('local','network')),
 enabled INTEGER NOT NULL CHECK(enabled IN(0,1)),
 health TEXT NOT NULL CHECK(length(health)>0),
 follow_symlinks INTEGER NOT NULL CHECK(follow_symlinks IN(0,1)),
 interval_seconds INTEGER NOT NULL CHECK(interval_seconds=0 OR interval_seconds>=900),
 identity_confirmed INTEGER NOT NULL CHECK(identity_confirmed IN(0,1)),
 next_scan_at TEXT NOT NULL,
 last_complete_at TEXT NOT NULL,
 last_progress_at TEXT NOT NULL,
 retained_bytes INTEGER NOT NULL,
 CONSTRAINT ia_configuration_source_bytes CHECK(retained_bytes=96+length(CAST(command_kind AS BLOB))+length(CAST(source_id AS BLOB))+length(CAST(source_name AS BLOB))+length(CAST(source_incarnation AS BLOB))+length(CAST(configured_root AS BLOB))+length(CAST(resolved_root AS BLOB))+length(CAST(root_identity AS BLOB))+length(CAST(source_kind AS BLOB))+length(CAST(classification AS BLOB))+length(CAST(health AS BLOB))+length(CAST(next_scan_at AS BLOB))+length(CAST(last_complete_at AS BLOB))+length(CAST(last_progress_at AS BLOB))),
 CHECK(command_kind<>'configure_source' OR ordinal=0),
 PRIMARY KEY(original_operation_id,command_incarnation,command_sequence,command_kind,ordinal),
 FOREIGN KEY(original_operation_id,command_incarnation,command_sequence,command_kind)
 REFERENCES catalog_configuration_receipts(original_operation_id,command_incarnation,command_sequence,command_kind)
 ON DELETE NO ACTION ON UPDATE NO ACTION
) WITHOUT ROWID, STRICT;
CREATE UNIQUE INDEX catalog_configuration_source_once ON catalog_configuration_sources(original_operation_id,command_incarnation,command_sequence,command_kind,source_id);
